92	func runReplay(args []string) {
93		versionID := ""
94		rest := args
95		if len(rest) >= 1 && strings.HasPrefix(rest[0], "--version=") {
96			versionID = strings.TrimPrefix(rest[0], "--version=")
97			rest = rest[1:]
98		} else if len(rest) >= 2 && rest[0] == "--version" {
99			versionID = rest[1]
100			rest = rest[2:]
101		}
102		if len(rest) != 2 {
103			fmt.Fprintln(os.Stderr, "usage: mevwatch replay [--version <id>] <input-file> <archive-dir>")
104			os.Exit(2)
105		}
106		var reports []mevwatch.Report
107		var err error
108		if versionID != "" {
109			reports, err = mevwatch.ReplayFileWithVersion(rest[0], rest[1], versionID)
110		} else {
111			reports, err = mevwatch.ReplayFile(rest[0], rest[1])
112		}
113		if err != nil {
114			fmt.Fprintf(os.Stderr, "replay: %v\n", err)
115			os.Exit(1)
116		}
117		for _, report := range reports {
118			writeJSON(report)
119		}
120	}
