122	func runRules(args []string) {
123		if len(args) < 1 {
124			fmt.Fprintln(os.Stderr, "usage: mevwatch rules <list|show|register|enable> ...")
125			os.Exit(2)
126		}
127		switch args[0] {
128		case "list":
129			if len(args) != 2 {
130				fmt.Fprintln(os.Stderr, "usage: mevwatch rules list <archive-dir>")
131				os.Exit(2)
132			}
133			versions, enabled, err := mevwatch.ListVersions(args[1])
134			if err != nil {
135				fmt.Fprintf(os.Stderr, "rules list: %v\n", err)
136				os.Exit(1)
137			}
138			writeJSON(struct {
139				Enabled  string                 `json:"enabled"`
140				Versions []mevwatch.RuleVersion `json:"versions"`
141			}{Enabled: enabled, Versions: versions})
142		case "show":
143			if len(args) != 3 {
144				fmt.Fprintln(os.Stderr, "usage: mevwatch rules show <archive-dir> <version-id>")
145				os.Exit(2)
146			}
147			version, err := mevwatch.GetVersion(args[1], args[2])
148			if err != nil {
149				fmt.Fprintf(os.Stderr, "rules show: %v\n", err)
150				os.Exit(1)
151			}
152			writeJSON(version)
153		case "register":
154			if len(args) != 3 {
155				fmt.Fprintln(os.Stderr, "usage: mevwatch rules register <archive-dir> <spec-file>")
156				os.Exit(2)
157			}
158			var raw []byte
159			var err error
160			if args[2] == "-" {
161				raw, err = io.ReadAll(os.Stdin)
162			} else {
163				raw, err = os.ReadFile(args[2])
164			}
165			if err != nil {
166				fmt.Fprintf(os.Stderr, "rules register: %v\n", err)
167				os.Exit(1)
168			}
169			version, created, err := mevwatch.RegisterVersion(args[1], raw)
170			if err != nil {
171				fmt.Fprintf(os.Stderr, "rules register: %v\n", err)
172				os.Exit(1)
173			}
174			writeJSON(struct {
175				Created bool                 `json:"created"`
176				Version mevwatch.RuleVersion `json:"version"`
177			}{Created: created, Version: version})
178		case "enable":
179			if len(args) != 3 {
180				fmt.Fprintln(os.Stderr, "usage: mevwatch rules enable <archive-dir> <version-id>")
181				os.Exit(2)
182			}
183			version, err := mevwatch.EnableVersion(args[1], args[2])
184			if err != nil {
185				fmt.Fprintf(os.Stderr, "rules enable: %v\n", err)
186				os.Exit(1)
187			}
188			writeJSON(version)
189		default:
190			fmt.Fprintf(os.Stderr, "unknown rules subcommand %q\n", args[0])
191			usage()
192			os.Exit(2)
193		}
194	}
