93	func TestGenerateAlertsIdempotent(t *testing.T) {
94		dir := t.TempDir()
95		mustReplay(t, dir, twoFindingsInput)
96	
97		first, err := GenerateAlerts(dir, "1", "ops", 10, 10, 3)
98		if err != nil {
99			t.Fatal(err)
100		}
101		if len(first) != 1 {
102			t.Fatalf("first run: got %d, want 1", len(first))
103		}
104		// Repeated generation, wider range, overlapping range, and a "restart"
105		// (fresh call against the same on-disk archive) create nothing new while
106		// the threshold stays at 3 (the severity-2 displacement is simply
107		// ineligible, not processed).
108		for _, bounds := range [][2]uint64{{10, 10}, {0, 100}, {5, 15}, {10, 10}} {
109			again, err := GenerateAlerts(dir, "1", "ops", bounds[0], bounds[1], 3)
110			if err != nil {
111				t.Fatal(err)
112			}
113			if len(again) != 0 {
114				t.Fatalf("range %d-%d re-generated %d records: %+v", bounds[0], bounds[1], len(again), again)
115			}
116		}
117		// Re-importing the same block still cannot make the sandwich alert twice.
118		mustReplay(t, dir, twoFindingsInput)
119		again, err := GenerateAlerts(dir, "1", "ops", 0, 100, 3)
120		if err != nil {
121			t.Fatal(err)
122		}
123		if len(again) != 0 {
124			t.Fatalf("re-import re-generated records: %+v", again)
125		}
126		// Lowering the threshold backfills the displacement once, then never again.
127		backfill, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
128		if err != nil {
129			t.Fatal(err)
130		}
131		if len(backfill) != 1 || backfill[0].Finding.Kind != "displacement" {
132			t.Fatalf("threshold backfill: got %+v, want the one displacement", backfill)
133		}
134		after, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
135		if err != nil {
136			t.Fatal(err)
137		}
138		if len(after) != 0 {
139			t.Fatalf("backfilled displacement re-generated: %+v", after)
140		}
141	}
