557			{"negative start", `{"id":"s","chainId":"1","pool":"p","kind":"sandwich","channel":"c","startHeight":-1,"endHeight":2,"reason":"r"}`},
558			{"fractional end", `{"id":"s","chainId":"1","pool":"p","kind":"sandwich","channel":"c","startHeight":1,"endHeight":2.5,"reason":"r"}`},
559			{"overflow end", `{"id":"s","chainId":"1","pool":"p","kind":"sandwich","channel":"c","startHeight":1,"endHeight":18446744073709551616,"reason":"r"}`},
560			{"start after end", `{"id":"s","chainId":"1","pool":"p","kind":"sandwich","channel":"c","startHeight":3,"endHeight":2,"reason":"r"}`},
561			{"missing reason", `{"id":"s","chainId":"1","pool":"p","kind":"sandwich","channel":"c","startHeight":1,"endHeight":2}`},
562			{"blank reason", `{"id":"s","chainId":"1","pool":"p","kind":"sandwich","channel":"c","startHeight":1,"endHeight":2,"reason":""}`},
